53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        String telephone = toE164(owner.getTelephone());
107	        if (telephone == null) {
108	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
109	        }
110	        owner.setTelephone(telephone);
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        if (isTelephoneInUse(telephone)) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
118	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    /**
130	     * Build the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}
131	     * where LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
132	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
133	     * (e.g. {@code 'SMI-0007'}).
134	     */
135	    private String nextCustomerCode(String lastName) {
136	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
137	        int sequence = this.clinicService.findAllOwners().size() + 1;
138	        return String.format("%s-%04d", last3, sequence);
139	    }
140	
141	    /**
142	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
143	     * cannot form a valid E.164 number.
144	     *
145	     * <p>A leading '+' and country code are kept when present; otherwise country code
146	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
147	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
148	     * carry 8 to 15 digits after the '+'.
149	     */
150	    private String toE164(String telephone) {
151	        if (telephone == null) {
152	            return null;
153	        }
154	        boolean hasCountryCode = telephone.trim().startsWith("+");
155	        String digits = telephone.replaceAll("\\D", "");
156	        String e164;
157	        if (hasCountryCode) {
158	            e164 = digits;
159	        } else {
160	            if (digits.startsWith("0")) {
161	                digits = digits.substring(1);
162	            }
163	            e164 = "61" + digits;
164	        }
165	        if (e164.length() < 8 || e164.length() > 15) {
166	            return null;
167	        }
168	        return "+" + e164;
169	    }
170	
171	    /**
172	     * Whether any existing owner already holds the given telephone number. Both the
173	     * candidate and each stored number are compared in E.164 form, so the check does not
174	     * depend on how each was originally formatted.
175	     */
176	    private boolean isTelephoneInUse(String telephone) {
177	        return this.clinicService.findAllOwners().stream()
178	            .map(Owner::getTelephone)
179	            .filter(Objects::nonNull)
180	            .map(this::toE164)
181	            .filter(Objects::nonNull)
182	            .anyMatch(telephone::equals);
183	    }
184	
185	    /**
186	     * Whether any existing owner already shares a household with the candidate, i.e. has both
187	     * the same lastName and the same address. Both fields are compared case-insensitively and
188	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
189	     * trimmed), so the check does not depend on casing or spacing.
190	     */
191	    private boolean isHouseholdInUse(String lastName, String address) {
192	        String candidateLastName = normalize(lastName);
193	        String candidateAddress = normalize(address);
194	        return this.clinicService.findAllOwners().stream()
195	            .anyMatch(existing -> normalize(existing.getLastName()).equals(candidateLastName)
196	                && normalize(existing.getAddress()).equals(candidateAddress));
197	    }
198	
199	    /**
200	     * Normalize a value for household comparison: trim, collapse internal whitespace runs to a
201	     * single space and lower-case. A null value normalizes to the empty string.
202	     */
203	    private String normalize(String value) {
204	        if (value == null) {
205	            return "";
206	        }
207	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
213	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
214	        if (currentOwner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        currentOwner.setAddress(ownerFieldsDto.getAddress());
218	        currentOwner.setCity(ownerFieldsDto.getCity());
219	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
220	        currentOwner.setLastName(ownerFieldsDto.getLastName());
221	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
222	        this.clinicService.saveOwner(currentOwner);
223	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Transactional
228	    @Override
229	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
230	        Owner owner = this.clinicService.findOwnerById(ownerId);
231	        if (owner == null) {
232	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	        }
234	        this.clinicService.deleteOwner(owner);
235	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner == null) {
243	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	        }
245	        HttpHeaders headers = new HttpHeaders();
246	        Pet pet = petMapper.toPet(petFieldsDto);
247	        owner.setId(ownerId);
248	        pet.setOwner(owner);
249	        pet.getType().setName(null);
250	        this.clinicService.savePet(pet);
251	        PetDto petDto = petMapper.toPetDto(pet);
252	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
253	            .buildAndExpand(pet.getId()).toUri());
254	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
260	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
261	        if (currentOwner != null) {
262	            Pet currentPet = this.clinicService.findPetById(petId);
263	            if (currentPet != null) {
264	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
265	                currentPet.setName(petFieldsDto.getName());
266	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
267	                this.clinicService.savePet(currentPet);
268	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
269	            }
270	        }
271	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	    }
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
277	        HttpHeaders headers = new HttpHeaders();
278	        Visit visit = visitMapper.toVisit(visitFieldsDto);
279	        Pet pet = new Pet();
280	        pet.setId(petId);
281	        visit.setPet(pet);
282	        this.clinicService.saveVisit(visit);
283	        VisitDto visitDto = visitMapper.toVisitDto(visit);
284	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
285	            .buildAndExpand(visit.getId()).toUri());
286	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
287	    }
288	
289	
290	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
291	    @Override
292	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
293	        Owner owner = this.clinicService.findOwnerById(ownerId);
294	        if (owner != null) {
295	            Pet pet = owner.getPet(petId);
296	            if (pet != null) {
297	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
298	            }
299	        }
300	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
301	    }
302	}
