28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
63	    private Set<Pet> pets;
64	
65	    public String getAddress() {
66	        return this.address;
67	    }
68	
69	    public void setAddress(String address) {
70	        this.address = address;
71	    }
72	
73	    public String getCity() {
74	        return this.city;
75	    }
76	
77	    public void setCity(String city) {
78	        this.city = city;
79	    }
80	
81	    public String getTelephone() {
82	        return this.telephone;
83	    }
84	
85	    public void setTelephone(String telephone) {
86	        this.telephone = telephone;
87	    }
88	
89	    public String getEmail() {
90	        return this.email;
91	    }
92	
93	    public void setEmail(String email) {
94	        this.email = email == null ? null : email.toLowerCase();
95	    }
96	
97	    public LocalDate getRegistrationDate() {
98	        return this.registrationDate;
99	    }
100	
101	    public void setRegistrationDate(LocalDate registrationDate) {
102	        this.registrationDate = registrationDate;
103	    }
104	
105	    public String getCustomerCode() {
106	        return this.customerCode;
107	    }
108	
109	    public void setCustomerCode(String customerCode) {
110	        this.customerCode = customerCode;
111	    }
112	
113	    /**
114	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
115	     */
116	    public String getDisplayName() {
117	        return this.getLastName() + ", " + this.getFirstName();
118	    }
119	
120	    /**
121	     * The owner's initials: the upper-cased first letters of firstName and lastName,
122	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
123	     */
124	    public String getInitials() {
125	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
126	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
127	    }
128	
129	    protected Set<Pet> getPetsInternal() {
130	        if (this.pets == null) {
131	            this.pets = new HashSet<>();
132	        }
133	        return this.pets;
134	    }
135	
136	    protected void setPetsInternal(Set<Pet> pets) {
137	        this.pets = pets;
138	    }
139	
140	    public List<Pet> getPets() {
141	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
142	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
143	        return Collections.unmodifiableList(sortedPets);
144	    }
145	
146	    public void setPets(List<Pet> pets) {
147	        this.pets = new HashSet<>(pets);
148	    }
149	
150	    public void addPet(Pet pet) {
151	        getPetsInternal().add(pet);
152	        pet.setOwner(this);
153	    }
154	
155	    /**
156	     * Return the Pet with the given name, or null if none found for this Owner.
157	     *
158	     * @param name to test
159	     * @return true if pet name is already in use
160	     */
161	    public Pet getPet(String name) {
162	        return getPet(name, false);
163	    }
164	
165	    /**
166	     * Return the Pet with the given name, or null if none found for this Owner.
167	     *
168	     * @param name to test
169	     * @return true if pet name is already in use
170	     */
171	    public Pet getPet(String name, boolean ignoreNew) {
172	        name = name.toLowerCase();
173	        for (Pet pet : getPetsInternal()) {
174	            if (!ignoreNew || !pet.isNew()) {
175	                String compName = pet.getName();
176	                compName = compName.toLowerCase();
177	                if (compName.equals(name)) {
178	                    return pet;
179	                }
180	            }
181	        }
182	        return null;
183	    }
184	
185	    public Pet getPet(Integer petId) {
186	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
187	    }
188	
189	    @Override
190	    public String toString() {
191	        return new ToStringCreator(this)
192	
193	            .append("id", this.getId())
194	            .append("new", this.isNew())
195	            .append("lastName", this.getLastName())
196	            .append("firstName", this.getFirstName())
197	            .append("address", this.address)
198	            .append("city", this.city)
199	            .append("telephone", this.telephone)
200	            .append("email", this.email)
201	            .toString();
202	    }
203	}
